content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --secondary-color: #10b981;
  --secondary-hover: #059669;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-sub: #4b5563;
  --border-radius: 12px;
  --shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg-color: #111827;
    --card-bg: #1f2937;
    --text-main: #f9fafb;
    --text-sub: #9ca3af;
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.app-container {
  width: 100%;
  max-width: 100%;
  padding: 24px 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

.header {
  width: 100%;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.title {
  font-size: 24px;
  font-weight: 700;
  color: var(--text-main);
}

.progress-container {
  width: 100%;
  background-color: #e5e7eb;
  border-radius: 9999px;
  height: 8px;
  overflow: hidden;
}

.progress-bar {
  background-color: var(--primary-color);
  height: 100%;
  transition: width 0.3s ease;
}

.card-viewport {
  width: 100%;
  height: 280px;
  perspective: 1000px;
  cursor: pointer;
}

.flashcard {
  width: 100%;
  height: 100%;
  position: relative;
}

.flashcard-inner {
  position: relative;
  width: 100%;
  height: 100%;
  text-align: center;
  transition: transform 0.6s cubic-bezier(0.4, 0.2, 0.2, 1);
  transform-style: preserve-3d;
  box-shadow: var(--shadow);
  border-radius: var(--border-radius);
  background-color: var(--card-bg);
  will-change: transform;
}

.flashcard.is-flipped .flashcard-inner {
  transform: rotateY(180deg);
}

.flashcard-front,
.flashcard-back {
  position: absolute;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 24px;
  border-radius: var(--border-radius);
  background-color: var(--card-bg);
}

.flashcard-back {
  transform: rotateY(180deg);
  background-color: #fef3c7;
}

@media (prefers-color-scheme: dark) {
  .flashcard-back {
    background-color: #372f1b;
  }
}

.card-text-main {
  font-size: 32px;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 8px;
}

.card-text-sub {
  font-size: 14px;
  color: var(--text-sub);
}

.card-example {
  font-size: 14px;
  font-style: italic;
  color: var(--text-sub);
  margin-top: 16px;
  padding: 8px 12px;
  background-color: rgba(0, 0, 0, 0.03);
  border-radius: 6px;
  max-width: 100%;
}

@media (prefers-color-scheme: dark) {
  .card-example {
    background-color: rgba(255, 255, 255, 0.05);
  }
}

.controls {
  display: flex;
  gap: 12px;
  width: 100%;
}

.btn {
  flex: 1;
  padding: 12px 16px;
  font-size: 16px;
  font-weight: 600;
  border: none;
  border-radius: var(--border-radius);
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  color: #ffffff;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--danger-color);
}

.btn-primary:hover {
  background-color: var(--danger-hover);
}

.btn-secondary {
  background-color: var(--secondary-color);
}

.btn-secondary:hover {
  background-color: var(--secondary-hover);
}

.stats-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  width: 100%;
  padding: 24px;
  background-color: var(--card-bg);
  border-radius: var(--border-radius);
  box-shadow: var(--shadow);
  text-align: center;
}

.restart-btn {
  padding: 12px 24px;
  font-size: 16px;
  font-weight: 600;
  background-color: var(--primary-color);
  color: #ffffff;
  border: none;
  border-radius: var(--border-radius);
  cursor: pointer;
  transition: background-color 0.2s;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}

.restart-btn:hover {
  background-color: var(--primary-hover);
}

export interface Flashcard {
  id: string;
  english: string;
  japanese: string;
  example: string;
  difficulty?: 'easy' | 'hard';
  category?: string;
  isFavorite?: boolean;
}

export interface StudyHistory {
  cardId: string;
  isKnown: boolean;
  timestamp: number;
}

export interface SessionData {
  sessionId: string;
  totalCards: number;
  correctCount: number;
  incorrectCount: number;
  history: StudyHistory[];
}

export interface AppState {
  currentIndex: number;
  isFlipped: boolean;
  knownCount: number;
  unknownCount: number;
  isFinished: boolean;
  history?: StudyHistory[];
}

import { useState, useEffect, useCallback } from 'react';
import { Flashcard, AppState } from './types';
import './index.css';

const sampleCards: Flashcard[] = [
  { id: '1', english: 'apple', japanese: 'りんご', example: 'I eat an apple every day.' },
  { id: '2', english: 'book', japanese: '本', example: 'She is reading a good book.' },
  { id: '3', english: 'cat', japanese: '猫', example: 'The cat is sleeping on the sofa.' },
  { id: '4', english: 'dog', japanese: '犬', example: 'My dog likes running in the park.' },
  { id: '5', english: 'elephant', japanese: '象', example: 'We saw a big elephant at the zoo.' },
  { id: '6', english: 'flower', japanese: '花', example: 'The flowers in the garden are beautiful.' },
  { id: '7', english: 'guitar', japanese: 'ギター', example: 'He is playing the guitar.' },
  { id: '8', english: 'house', japanese: '家', example: 'They live in a big house.' },
  { id: '9', english: 'island', japanese: '島', example: 'Okinawa is a beautiful island.' },
  { id: '10', english: 'juice', japanese: 'ジュース', example: 'Would you like some orange juice?' },
];

function useFlashcards(cards: Flashcard[]) {
  const [state, setState] = useState<AppState>({
    currentIndex: 0,
    isFlipped: false,
    knownCount: 0,
    unknownCount: 0,
    isFinished: false,
  });

  const currentCard = cards[state.currentIndex];
  const progressPercent = (state.currentIndex / cards.length) * 100;

  const handleFlip = useCallback(() => {
    setState((prev) => ({ ...prev, isFlipped: !prev.isFlipped }));
  }, []);

  const handleAnswer = useCallback((isKnown: boolean) => {
    setState((prev) => {
      const nextIndex = prev.currentIndex + 1;
      const isFinished = nextIndex >= cards.length;
      return {
        ...prev,
        currentIndex: isFinished ? prev.currentIndex : nextIndex,
        isFlipped: false,
        knownCount: isKnown ? prev.knownCount + 1 : prev.knownCount,
        unknownCount: !isKnown ? prev.unknownCount + 1 : prev.unknownCount,
        isFinished,
      };
    });
  }, [cards.length]);

  const handleRestart = useCallback(() => {
    setState({
      currentIndex: 0,
      isFlipped: false,
      knownCount: 0,
      unknownCount: 0,
      isFinished: false,
    });
  }, []);

  return {
    state,
    currentCard,
    progressPercent,
    handleFlip,
    handleAnswer,
    handleRestart,
  };
}

export default function App() {
  const {
    state,
    currentCard,
    progressPercent,
    handleFlip,
    handleAnswer,
    handleRestart,
  } = useFlashcards(sampleCards);

  // キーボード操作の対応 (スペース/Enterで裏返し、左矢印で知らない、右矢印で知っている)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (state.isFinished) {
        if (e.key === 'Enter' || e.key === 'r' || e.key === 'R') {
          handleRestart();
        }
        return;
      }

      if (e.key === ' ' || e.key === 'Enter') {
        e.preventDefault();
        handleFlip();
      } else if (e.key === 'ArrowLeft') {
        e.preventDefault();
        handleAnswer(false);
      } else if (e.key === 'ArrowRight') {
        e.preventDefault();
        handleAnswer(true);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [state.isFinished, handleFlip, handleAnswer, handleRestart]);

  const totalAnswered = state.knownCount + state.unknownCount;
  const accuracyRate = totalAnswered > 0 ? Math.round((state.knownCount / totalAnswered) * 100) : 0;

  return (
    <div className="app-container">
      <div className="header">
        <h1 className="title">英単語暗記カード</h1>
        <div className="progress-container">
          <div className="progress-bar" style={{ width: `${progressPercent}%` }}></div>
        </div>
        {!state.isFinished && (
          <div className="card-text-sub">
            カード {state.currentIndex + 1} / {sampleCards.length} (Space: めくる / ←: 知らない / →: 知っている)
          </div>
        )}
      </div>

      {state.isFinished ? (
        <div className="stats-container">
          <h2 className="title">学習完了！</h2>
          <p className="card-text-sub">お疲れ様でした。学習結果はこちらです。</p>

          <div style={{ width: '100%', margin: '8px 0', textAlign: 'center' }}>
            <div style={{ fontSize: '18px', fontWeight: 'bold', marginBottom: '6px' }}>
              正答率: {accuracyRate}%
            </div>
            <div className="progress-container">
              <div className="progress-bar" style={{ width: `${accuracyRate}%`, backgroundColor: 'var(--secondary-color)' }}></div>
            </div>
          </div>

          <p>分かった単語: <strong>{state.knownCount}</strong> 個</p>
          <p>要復習の単語: <strong>{state.unknownCount}</strong> 個</p>

          <button className="restart-btn" onClick={handleRestart}>
            もう一度学習する
          </button>
        </div>
      ) : (
        <>
          <div className="card-viewport" onClick={handleFlip}>
            <div className={`flashcard ${state.isFlipped ? 'is-flipped' : ''}`}>
              <div className="flashcard-inner">
                <div className="flashcard-front">
                  <div className="card-text-main">{currentCard.english}</div>
                  <div className="card-text-sub">クリックまたはスペースキーで意味を確認</div>
                </div>
                <div className="flashcard-back">
                  <div className="card-text-main">{currentCard.japanese}</div>
                  <div className="card-example">{currentCard.example}</div>
                  <div className="card-text-sub" style={{ marginTop: '8px' }}>クリックまたはスペースキーで英語に戻す</div>
                </div>
              </div>
            </div>
          </div>

          <div className="controls">
            <button className="btn btn-primary" onClick={() => handleAnswer(false)}>
              知らない (←)
            </button>
            <button className="btn btn-secondary" onClick={() => handleAnswer(true)}>
              知っている (→)
            </button>
          </div>
        </>
      )}
    </div>
  );
}
